import{_ as o,o as t,c as r,ae as l}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"部署（GitHub + Vercel，可控版）","description":"","frontmatter":{},"headers":[],"relativePath":"runbooks/deployment.md","filePath":"runbooks/deployment.md"}'),d={name:"runbooks/deployment.md"};function c(i,e,a,n,s,p){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="部署-github-vercel-可控版" tabindex="-1">部署（GitHub + Vercel，可控版） <a class="header-anchor" href="#部署-github-vercel-可控版" aria-label="Permalink to &quot;部署（GitHub + Vercel，可控版）&quot;">​</a></h1><p><strong>類型</strong>：runbook | <strong>權重</strong>：2</p><p>本專案使用 <strong>GitHub Actions 控版控與部署節奏</strong>，部署目標為 <strong>Vercel</strong>。<br> 重點：CI 自動、Release 手動；App <strong>preview</strong> 手動驗收、<strong>production</strong> 在 CI 成功後自動或手動部署。文件站走 <strong>GitHub Pages</strong>（見 <a href="./github-pages-docs.html">github-pages-docs</a>），與 App 分離。</p><h2 id="發布通道" tabindex="-1">發布通道 <a class="header-anchor" href="#發布通道" aria-label="Permalink to &quot;發布通道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>通道</th><th>平台</th><th>內容</th></tr></thead><tbody><tr><td>文件</td><td>GitHub Pages (<code>gh-pages</code>)</td><td>VitePress 靜態站</td></tr><tr><td>App 測試</td><td>Vercel <strong>preview</strong> URL</td><td>完整 Remix SSR + API</td></tr><tr><td>App 正式</td><td><code>ai-search-portal.vercel.app</code></td><td>production domain</td></tr></tbody></table><p>對外：文件看 Pages；試產品用 Vercel preview；正式 Demo 用 production domain。</p><h2 id="workflow-一覽" tabindex="-1">Workflow 一覽 <a class="header-anchor" href="#workflow-一覽" aria-label="Permalink to &quot;Workflow 一覽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>檔案</th><th>觸發</th><th>用途</th></tr></thead><tbody><tr><td>CI</td><td><code>.github/workflows/ci.yml</code></td><td>PR、push <code>main</code></td><td>品質閘門（build / test / lint / typecheck）</td></tr><tr><td>Release</td><td><code>.github/workflows/release.yml</code></td><td><code>workflow_dispatch</code></td><td>建立 tag + GitHub Release（可 prerelease）</td></tr><tr><td>Deploy to Vercel</td><td><code>.github/workflows/deploy-vercel.yml</code></td><td><code>workflow_dispatch</code>；<strong>main CI 成功後</strong> <code>workflow_run</code> → production</td><td>preview / production 部署至 Vercel</td></tr><tr><td>deploy-docs</td><td><code>.github/workflows/deploy-docs.yml</code></td><td>push <strong><code>docs/**</code></strong>（或本 workflow）；<code>workflow_dispatch</code></td><td>VitePress → <code>gh-pages</code>（與 Vercel／<code>package.json</code> 無關）</td></tr></tbody></table><blockquote><p><strong>獨立通道</strong>：App 上 Vercel、文件走 Pages。改 <code>package.json</code>／lockfile <strong>不會</strong>再觸發 <code>deploy-docs</code>（避免「跟 Vercel 一起上 gh-pages」的誤感）。依賴變更若需重建文件站：Actions → deploy-docs → Run workflow。</p></blockquote><h2 id="冷啟動-lcp-app" tabindex="-1">冷啟動／LCP（App） <a class="header-anchor" href="#冷啟動-lcp-app" aria-label="Permalink to &quot;冷啟動／LCP（App）&quot;">​</a></h2><ul><li>Document shell <strong>不</strong> <code>await ensureSeeded()</code>——氛圍底＋品牌可先畫；seed 留在需要 mock 資料的路由。</li><li>首頁 LCP 候選：<code>/marketing/home-atmosphere.*</code>（prefer webp／svg，目標 <strong>≤ ~200KB</strong>）；<code>root</code> links 有 preload。</li><li>Web Vitals 仍走既有 reporter；本輪不開 PostHog P75 真面板。</li></ul><h2 id="必要-github-secrets-repository-或-environment" tabindex="-1">必要 GitHub Secrets（repository 或 environment） <a class="header-anchor" href="#必要-github-secrets-repository-或-environment" aria-label="Permalink to &quot;必要 GitHub Secrets（repository 或 environment）&quot;">​</a></h2><ul><li><code>VERCEL_TOKEN</code></li><li><code>VERCEL_ORG_ID</code></li><li><code>VERCEL_PROJECT_ID</code></li></ul><p>建議在 GitHub 建立兩個 Environment：</p><ul><li><code>preview</code></li><li><code>production</code></li></ul><p>並把同名 secrets 設在對應 environment，搭配 reviewers/protection 控制 production 部署權限。</p><h2 id="建議-vercel-專案設定" tabindex="-1">建議 Vercel 專案設定 <a class="header-anchor" href="#建議-vercel-專案設定" aria-label="Permalink to &quot;建議 Vercel 專案設定&quot;">​</a></h2><ul><li>保留 Vercel 與 GitHub 連線（供 metadata 與 preview 記錄）。</li><li>將 production 的實際上線操作統一由 <strong>GitHub <code>Deploy to Vercel</code> workflow</strong> 觸發。</li><li>若需完全避免「push main 自動上線」，請在 Vercel 專案設定停用 Git auto-deploy（或限制 production branch），把上線權限集中在 GitHub workflow + environment approvals。</li></ul><h2 id="發版流程-版控" tabindex="-1">發版流程（版控） <a class="header-anchor" href="#發版流程-版控" aria-label="Permalink to &quot;發版流程（版控）&quot;">​</a></h2><ol><li>開發於 <code>feature/*</code>，PR 合併到 <code>main</code>（CI 必須全綠）。</li><li>需對外版本時，手動執行 <strong>Release workflow</strong>： <ul><li><code>version</code>: <code>vX.Y.Z</code>（或 <code>X.Y.Z</code>）</li><li><code>target_ref</code>: 預設 <code>main</code>（也可指定 SHA）</li><li><code>prerelease</code>: true/false</li></ul></li><li>workflow 會建立 tag 並產生 GitHub Release（含 auto notes）。</li></ol><h2 id="部署流程-可控" tabindex="-1">部署流程（可控） <a class="header-anchor" href="#部署流程-可控" aria-label="Permalink to &quot;部署流程（可控）&quot;">​</a></h2><ol><li><strong>首次或重大變更</strong>：手動執行 <strong>Deploy to Vercel</strong> → <code>environment: preview</code>，驗收 <code>/catalog-search</code> 等路由後再 production。</li><li><strong>main 合併後</strong>：CI 全綠 → <code>deploy-vercel</code> 自動以 <code>workflow_run</code> 部署 <strong>production</strong>（亦可改用手動 <code>workflow_dispatch</code>）。</li><li>手動部署參數： <ul><li><code>environment</code>: <code>preview</code> 或 <code>production</code></li><li><code>target_ref</code>: branch/tag/SHA（預設 <code>main</code>）</li></ul></li><li>workflow 會先執行： <ul><li><code>pnpm install --frozen-lockfile</code></li><li><code>pnpm run lint:openapi</code></li><li><code>pnpm run verify:openapi-codegen</code></li><li><code>vercel build</code>（Linux；需 <code>vite.config.ts</code> 內 <code>process.env.VERCEL</code> 時啟用 <code>vercelPreset</code>）</li></ul></li><li>通過後 <code>vercel deploy --prebuilt</code>，Job Summary 顯示 deploy URL。</li></ol><h3 id="本機注意-windows" tabindex="-1">本機注意（Windows） <a class="header-anchor" href="#本機注意-windows" aria-label="Permalink to &quot;本機注意（Windows）&quot;">​</a></h3><ul><li><strong>不要</strong>在本機跑 <code>vercel build --prebuilt</code>（Remix 動態路由 symlink 含 <code>:</code>，Windows 會失敗）。</li><li>正式部署路徑：<strong>GitHub Actions（ubuntu-latest）</strong> 或 Vercel 雲端 <code>vercel deploy --prod</code>（非 prebuilt）。</li></ul><h2 id="版本與-changelog-changesets" tabindex="-1">版本與 Changelog（Changesets） <a class="header-anchor" href="#版本與-changelog-changesets" aria-label="Permalink to &quot;版本與 Changelog（Changesets）&quot;">​</a></h2><ul><li>使用 <strong>@changesets/cli</strong> 管理版本與 CHANGELOG。</li><li>對外可見變更請在 PR 內執行 <code>pnpm run changeset</code>。</li><li>手動 release 前可先在本地跑 <code>changeset version</code> 並提交（視團隊流程），或用 GitHub Release notes 做階段性發布記錄。</li></ul><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./local-dev.html">local-dev</a>：分支、PR、CI 與保護策略</li><li><a href="./../../CONTRIBUTING.html">CONTRIBUTING.md</a>：Quality checks</li></ul>',28)])])}const g=o(d,[["render",c]]);export{u as __pageData,g as default};
